function 비교심화() {
  console.log(1 === 1);      // true (값도 타입도 같음)
  console.log(1 == 1);       // true (값도 타입도 같음)
  console.log(1 === "1");    // false (타입이 다름: number vs string)
  console.log(1 == "1");     // true (== 는 타입 변환 후 비교하므로 같다고 판단)
  console.log("a" === "a");  // true
  console.log("a" == "a");   // true
  console.log(true === 1);   // false (boolean vs number, 타입이 다름)
  console.log(true == 1);    // true (== 는 true를 1로 변환해서 비교)
}

