function 기본자료형2() {
  // 1) Number - 숫자 (정수/실수 구분 없음)
  var 숫자 = 10;
  var 실수 = 3.14;
  console.log(typeof 숫자);  // "number"
  console.log(숫자.constructor.name);
  console.log(typeof 실수);  // "number"
  console.log(실수.constructor.name);


  // 2) String - 문자열
  var 문자 = "안녕하세요";
  var 문자2 = '작은따옴표도 가능';
  console.log(typeof 문자);  // "string"

  // 3) Boolean - 참/거짓
  var 참 = true;
  var 거짓 = false;
  console.log(typeof 참);  // "boolean"

  // 4) Undefined - 값이 아직 없음 (선언만 하고 값 안 넣음)
  var 아직없음;
  console.log(typeof 아직없음);  // "undefined"

  // 5) Null - 값이 "없다"는 걸 의도적으로 표시
  var 없음 = null;
  console.log(typeof 없음);  // "object" (자바스크립트의 유명한 버그성 특징!)
}

