function 객체(){
  var my_object = {"바나나":"banana","토마토":"tomato"};
  console.log(my_object.constructor.name);
  console.log(my_object);
  console.log(Object.keys(my_object));
  console.log(Object.values(my_object));
  console.log(Object.entries(my_object));
  console.log(my_object["토마토"]);

}

function 객체_추가기능() {

  // ==========================
  // 1. 객체 생성(Create)
  // ==========================
  var my_object = {
    "바나나": "banana",
    "토마토": "tomato"
  };

  console.log("객체 타입 :", my_object.constructor.name);
  console.log("객체 전체 :", my_object);

  // ==========================
  // 2. 객체 조회(Read)
  // ==========================
  console.log("Key 목록 :", Object.keys(my_object));
  console.log("Value 목록 :", Object.values(my_object));
  console.log("Entry 목록 :", Object.entries(my_object));

  console.log("토마토의 값 :", my_object["토마토"]);

  // ==========================
  // 3. 데이터 추가(Create)
  // ==========================
  my_object["사과"] = "apple";

  console.log("사과 추가 후");
  console.log(my_object);

  // ==========================
  // 4. 데이터 수정(Update)
  // ==========================
  my_object["토마토"] = "Tomato";

  console.log("토마토 수정 후");
  console.log(my_object);

  // ==========================
  // 5. 데이터 삭제(Delete)
  // ==========================
  delete my_object["바나나"];

  console.log("바나나 삭제 후");
  console.log(my_object);

}

