/**
 * 두 숫자를 더합니다.
 * @param {number} a 첫 번째 숫자
 * @param {number} b 두 번째 숫자
 * @return {number} 두 숫자를 더한 값
 */
function 더하기(a, b) {
  return a + b;
}

/**
 * 첫 번째 숫자에서 두 번째 숫자를 뺍니다.
 * @param {number} a 첫 번째 숫자
 * @param {number} b 두 번째 숫자
 * @return {number} 뺀 결과
 */
function 빼기(a, b) {
  return a - b;
}

/**
 * 두 숫자를 곱합니다.
 * @param {number} a 첫 번째 숫자
 * @param {number} b 두 번째 숫자
 * @return {number} 곱한 결과
 */
function 곱하기(a, b) {
  return a * b;
}

/**
 * 첫 번째 숫자를 두 번째 숫자로 나눕니다.
 * @param {number} a 나눠지는 숫자
 * @param {number} b 나누는 숫자
 * @return {number} 나눈 결과 (b가 0이면 에러 메시지 반환)
 */
function 나누기(a, b) {
  if (b === 0) {
    console.log("0으로 나눌 수 없습니다.");
    return null;
  }
  return a / b;
}

